"""Reading a tool's answer off the wire, and reaching one field inside it.

Split out of `assertions.py` because it is the part with no opinion: it knows the three
*measured* return shapes and nothing about whether an answer is correct.
"""

from __future__ import annotations

import json
from collections.abc import Mapping
from typing import Any

from .mcp_session import ToolResult

_MISSING = object()


class _Absent:
    """Sentinel for "this leaf must not exist", as an expected value.

    `None` cannot carry that meaning: `resolve_path` hands `None` back for a missing key, an
    out-of-range index and a walk through a scalar alike, so `{"primary_name.frist_name": None}`
    — a typo — compares `None == None` and passes in both halves of the check. Absence has to be
    said out loud to be falsifiable.
    """

    __slots__ = ()

    def __repr__(self) -> str:
        return "ABSENT"


ABSENT = _Absent()


def payload(result: ToolResult) -> Any:
    """The tool's own report, from wherever its return type puts it on the wire.

    Measured (`probes/observed.json::u3_structured_content`), and the reverse of what the plan
    assumed: the three bare-`str` tools are the only ones carrying `structuredContent`
    (`{"result": …}`) and the only ones with an `outputSchema`; `dict` tools carry none and put
    JSON in a single text part; `list` tools emit **one text part per element**, so joining the
    parts and parsing once would raise.
    """
    structured = result.structured
    if structured is not None:
        if isinstance(structured, Mapping) and set(structured) == {"result"}:
            return structured["result"]
        return structured
    values = [
        _decode(part.get("text", "")) for part in result.content if part.get("type") == "text"
    ]
    return values[0] if len(values) == 1 else values


def payload_list(result: ToolResult) -> list[Any]:
    """`payload` for a `list` tool, where a one-element answer must still be a list."""
    got = payload(result)
    return got if isinstance(got, list) else [got]


def _decode(text: str) -> Any:
    try:
        return json.loads(text)
    except ValueError:
        return text


def resolve_path(record: Any, path: str, default: Any = _MISSING) -> Any:
    """Walk a dotted field path; integer segments index into lists.

    `primary_name.surname_list.0.surname` is the shape person assertions need. Naming the leaf
    is the point: comparing whole records would grade every unrelated field the server fills in.
    """
    current = record
    for segment in path.split("."):
        if isinstance(current, (list, tuple)):
            index = int(segment)
            if index >= len(current):
                return _absent(default, path)
            current = current[index]
        elif isinstance(current, Mapping):
            if segment not in current:
                return _absent(default, path)
            current = current[segment]
        else:
            return _absent(default, path)
    return current


def _absent(default: Any, path: str) -> Any:
    if default is _MISSING:
        raise KeyError(path)
    return default
